<script>
(function(){const classSelect=document.getElementById('ta-class');const subjectSelect=document.getElementById('ta-subject');if(!classSelect||!subjectSelect)return;function refresh(){const classId=classSelect.value;for(const option of subjectSelect.options){if(!option.value)continue;option.hidden=option.dataset.class!==classId;option.disabled=option.hidden;}if(subjectSelect.selectedOptions[0]?.disabled||!classId)subjectSelect.value='';}classSelect.addEventListener('change',()=>{subjectSelect.value='';refresh()});refresh()})();
</script>
